namespace sv_e53e4e795be340d094aee89a19f79530.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    DateTimeOffset Timestamp,
    string Description,
    string Location);

using sv_e53e4e795be340d094aee89a19f79530.Client.Models;

namespace sv_e53e4e795be340d094aee89a19f79530.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_e53e4e795be340d094aee89a19f79530.Client.Models;

namespace sv_e53e4e795be340d094aee89a19f79530.Client.Services;

/// <summary>
/// IShipmentService implementation used in the WebAssembly environment.
/// Calls the server-side API over HTTP.
/// </summary>
public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await httpClient.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Shipment not found.");
    }
}

using sv_e53e4e795be340d094aee89a19f79530.Client.Models;
using sv_e53e4e795be340d094aee89a19f79530.Client.Services;

namespace sv_e53e4e795be340d094aee89a19f79530.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with seeded data.
/// </summary>
public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 20, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 8, 0, 0, TimeSpan.Zero), "Package picked up", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 15, 14, 30, 0, TimeSpan.Zero), "Departed facility", "New York, NY"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 16, 6, 0, 0, TimeSpan.Zero), "Arrived at hub", "Chicago, IL"),
            ]),

        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 15, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 12, 9, 0, 0, TimeSpan.Zero), "Package picked up", "Seattle, WA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 13, 11, 0, 0, TimeSpan.Zero), "In transit", "Portland, OR"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 16, 0, 0, TimeSpan.Zero), "Out for delivery", "San Francisco, CA"),
                new StatusUpdate(new DateTimeOffset(2026, 6, 14, 18, 45, 0, TimeSpan.Zero), "Delivered", "San Francisco, CA"),
            ]),

        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Dallas, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 22, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates:
            [
                new StatusUpdate(new DateTimeOffset(2026, 6, 16, 7, 0, 0, TimeSpan.Zero), "Label created", "Dallas, TX"),
            ]),
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_e53e4e795be340d094aee89a19f79530.Client.Models
@using sv_e53e4e795be340d094aee89a19f79530.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p>Loading shipment details for <strong>@TrackingNumber</strong>...</p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="error-container">
        <p class="error-message">@_errorMessage</p>
        <button @onclick="RetryLoad">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <div class="shipment-details">
        <h2>Shipment @_shipment.TrackingNumber</h2>
        <dl>
            <dt>Status</dt>
            <dd>@_shipment.Status</dd>
            <dt>Location</dt>
            <dd>@_shipment.Location</dd>
            <dt>Estimated Delivery</dt>
            <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
        </dl>

        <h3>Status History</h3>
        <ul class="status-updates">
            @foreach (var update in _shipment.StatusUpdates)
            {
                <li>
                    <time datetime="@update.Timestamp.ToString("o")">@update.Timestamp.ToString("g")</time>
                    &mdash; <strong>@update.Description</strong> (@update.Location)
                </li>
            }
        </ul>
    </div>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));

        _loading = true;
        _shipment = null;
        _errorMessage = null;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, _cts.Token);
        }
        catch (OperationCanceledException) when (_cts.IsCancellationRequested)
        {
            if (_cts.Token.IsCancellationRequested && _shipment is null && _errorMessage is null)
            {
                _errorMessage = "The request timed out. Please try again.";
                Logger.LogWarning("Shipment request for {TrackingNumber} timed out.", TrackingNumber);
            }
            // If cancelled due to navigation/dispose, we just stop silently.
        }
        catch (TaskCanceledException)
        {
            _errorMessage = "The request timed out. Please try again.";
            Logger.LogWarning("Shipment request for {TrackingNumber} timed out.", TrackingNumber);
        }
        catch (Exception ex)
        {
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
            Logger.LogError(ex, "Failed to load shipment {TrackingNumber}.", TrackingNumber);
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryLoad()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

